insert into programs (id, version, name, definition) values
  ('arnold-gym-6', 1, 'Arnold double split, six day', '{"id":"arnold-gym-6","version":1,"name":"Arnold double split, six day","blocks":9,"slots":[{"kind":"lift","key":"A"},{"kind":"lift","key":"B"},{"kind":"lift","key":"C"},{"kind":"lift","key":"D"},{"kind":"lift","key":"E"},{"kind":"lift","key":"F"}],"phases":[{"id":"base","name":"Base","color":"#2F6BB0","kg":"20","from":0,"to":17,"note":"Straight sets, no intensity tricks. Hit the top of every rep range on every set before you add load."},{"id":"load","name":"Load","color":"#E5A912","kg":"15","from":18,"to":35,"note":"Opening lifts go heavier and drop to 6-8. Drop sets come in on one nominated move per session."},{"id":"peak","name":"Peak","color":"#C93A2B","kg":"25","from":36,"to":53,"note":"Reps back up, drop sets stay, and the opening compound gets rest-pause. You should finish this ready for a week off."}],"tech":{"drop":{"label":"Drop set","when":"Final set only","steps":["Take the last set to the point where the next rep would stall.","Strip 25-30% in under 10 seconds. On dumbbells, grab the next pair down.","Go again to that same stall point. Expect roughly half the reps.","Blocks 4-5: one drop. Block 6 onward: two drops."]},"rp":{"label":"Rest-pause","when":"Final set only","steps":["Take the last set to one rep short of failure, then rack it.","Stand and breathe for 15 seconds. About five slow breaths.","Same weight, go again. Rack, 15 seconds, one more mini-set.","Expect roughly 8 / 4 / 2. If set two beats half of set one, add load next time.","Machine, spotter, or safety pins."]}},"sessions":{"A":{"letter":"A","title":"Chest + Back","sub":"Heavy, every move paired","ex":[{"id":"incline-barbell-press","name":"Incline dumbbell press","sets":4,"reps":"8-10","rest":90,"pair":1,"loadReps":"6-8","tech":"rp"},{"id":"wide-grip-pulldown","name":"Wide-grip pull-up / pulldown","sets":4,"reps":"8-10","rest":90,"pair":1},{"id":"weighted-dips","name":"Weighted dips","sets":4,"reps":"8-12","rest":75,"pair":2},{"id":"barbell-row","name":"Barbell row","sets":4,"reps":"8-10","rest":75,"pair":2},{"id":"smith-wide-press","name":"Wide-grip Smith press","sets":3,"reps":"10-12","rest":75,"pair":3},{"id":"seated-cable-row","name":"Seated cable row","sets":3,"reps":"10-12","rest":75,"pair":3},{"id":"cable-fly","name":"Cable fly","sets":3,"reps":"12-15","rest":60,"pair":4,"tech":"drop"},{"id":"straight-arm-pulldown","name":"Straight-arm pulldown","sets":3,"reps":"12-15","rest":60,"pair":4}]},"B":{"letter":"B","title":"Shoulders + Arms","sub":"Heavy, delts first","ex":[{"id":"arnold-press","name":"Arnold press","sets":4,"reps":"8-10","rest":90,"pair":1,"loadReps":"6-8","tech":"rp"},{"id":"face-pull","name":"Face pull","sets":4,"reps":"15","rest":90,"pair":1},{"id":"lateral-raise","name":"Lateral raise","sets":4,"reps":"12-15","rest":60,"pair":2,"tech":"drop"},{"id":"rear-delt-fly","name":"Rear delt fly","sets":4,"reps":"12-15","rest":60,"pair":2},{"id":"barbell-curl","name":"Barbell curl","sets":4,"reps":"8-10","rest":75,"pair":3},{"id":"close-grip-bench","name":"Close-grip Smith press","sets":4,"reps":"8-10","rest":75,"pair":3},{"id":"incline-db-curl","name":"Incline dumbbell curl","sets":3,"reps":"10-12","rest":60,"pair":4},{"id":"rope-pushdown","name":"Rope pushdown","sets":3,"reps":"10-12","rest":60,"pair":4},{"id":"hammer-curl","name":"Hammer curl","sets":3,"reps":"12","rest":60,"pair":5},{"id":"overhead-cable-ext","name":"Overhead cable extension","sets":3,"reps":"12","rest":60,"pair":5}]},"C":{"letter":"C","title":"Legs","sub":"Heavy, squat first","ex":[{"id":"back-squat","name":"Back squat","sets":5,"reps":"6-8","rest":150,"pair":null,"loadReps":"5-6"},{"id":"romanian-deadlift","name":"Romanian deadlift","sets":4,"reps":"8-10","rest":105,"pair":1},{"id":"hanging-knee-raise","name":"Hanging knee raise","sets":4,"reps":"12-15","rest":105,"pair":1},{"id":"leg-press","name":"Leg press","sets":3,"reps":"12-15","rest":90,"pair":null,"tech":"rp"},{"id":"lying-leg-curl","name":"Lying leg curl","sets":3,"reps":"12","rest":60,"pair":2},{"id":"leg-extension","name":"Leg extension","sets":3,"reps":"15","rest":60,"pair":2,"tech":"drop"},{"id":"standing-calf-raise","name":"Standing calf raise","sets":4,"reps":"15-20","rest":45,"pair":3},{"id":"cable-crunch","name":"Cable crunch","sets":4,"reps":"15","rest":45,"pair":3}]},"D":{"letter":"D","title":"Chest + Back","sub":"Volume, new angles","ex":[{"id":"flat-db-press","name":"Flat dumbbell press","sets":4,"reps":"10-12","rest":90,"pair":1,"loadReps":"8-10","tech":"rp"},{"id":"chest-supported-row","name":"Chest-supported row","sets":4,"reps":"10-12","rest":90,"pair":1},{"id":"incline-db-fly","name":"Incline dumbbell fly","sets":3,"reps":"12-15","rest":60,"pair":2},{"id":"single-arm-pulldown","name":"Single-arm lat pulldown","sets":3,"reps":"12 / side","rest":60,"pair":2},{"id":"db-pullover","name":"Dumbbell pullover","sets":3,"reps":"12-15","rest":60,"pair":3},{"id":"face-pull","name":"Face pull","sets":3,"reps":"15-20","rest":60,"pair":3},{"id":"flat-db-fly","name":"Flat dumbbell fly","sets":3,"reps":"12-15","rest":60,"pair":4,"tech":"drop"},{"id":"seated-cable-row","name":"Seated cable row","sets":3,"reps":"12-15","rest":60,"pair":4},{"id":"cable-crunch","name":"Cable crunch","sets":3,"reps":"15","rest":45,"pair":null}]},"E":{"letter":"E","title":"Shoulders + Arms","sub":"Volume, higher reps","ex":[{"id":"seated-db-press","name":"Seated dumbbell press","sets":4,"reps":"10-12","rest":75,"pair":1,"loadReps":"8-10"},{"id":"cable-upright-row","name":"Cable upright row","sets":4,"reps":"12-15","rest":75,"pair":1},{"id":"lateral-raise","name":"Lateral raise","sets":4,"reps":"15-20","rest":45,"pair":2,"tech":"drop"},{"id":"rear-delt-fly","name":"Rear delt fly","sets":4,"reps":"15-20","rest":45,"pair":2},{"id":"ez-curl","name":"EZ-bar curl","sets":3,"reps":"10-12","rest":60,"pair":3},{"id":"triceps-pushdown","name":"Triceps pushdown","sets":3,"reps":"12-15","rest":60,"pair":3},{"id":"hammer-curl","name":"Hammer curl","sets":3,"reps":"12-15","rest":60,"pair":4},{"id":"overhead-cable-ext","name":"Overhead cable extension","sets":3,"reps":"12-15","rest":60,"pair":4}]},"F":{"letter":"F","title":"Legs","sub":"Volume, posterior emphasis","ex":[{"id":"leg-press","name":"Leg press","sets":4,"reps":"12-15","rest":105,"pair":null,"loadReps":"10-12","tech":"rp"},{"id":"hip-thrust","name":"Barbell hip thrust","sets":4,"reps":"10-12","rest":90,"pair":1},{"id":"bulgarian-split-squat","name":"Bulgarian split squat","sets":3,"reps":"10-12 / side","rest":90,"pair":1},{"id":"lying-leg-curl","name":"Lying leg curl","sets":4,"reps":"12-15","rest":60,"pair":2,"tech":"drop"},{"id":"leg-extension","name":"Leg extension","sets":4,"reps":"15-20","rest":60,"pair":2},{"id":"seated-calf-raise","name":"Seated calf raise","sets":4,"reps":"15-20","rest":45,"pair":3},{"id":"hanging-knee-raise","name":"Hanging knee raise","sets":4,"reps":"15","rest":45,"pair":3}]}},"modes":{}}'::jsonb)
